import React, { useState } from "react";
import axios from "axios";

export default function Login() {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");

    const handleEmail = (e) => setEmail(e.target.value);
    const handlePassword = (e) => setPassword(e.target.value);

    const handleLogin = async () => {
        try {
            const response = await axios.post("http://localhost:5000/login", {
                email,
                password,
            });
    
            console.log(response.data);  // Log response to see the data returned
    
            // Check if the backend is sending firstName and lastName
            if (response.data.firstName && response.data.lastName) {
                localStorage.setItem("token", response.data.token);
                localStorage.setItem("firstName", response.data.firstName);
                localStorage.setItem("lastName", response.data.lastName);
    
                alert("Login successful!");
                window.location.href = "/";  // Redirect to home page after login
            } else {
                console.error("First Name and Last Name are missing in response");
            }
        } catch (error) {
            alert(error.response?.data?.error || "Login failed");
        }
    };
    
    

    return (
        <div>
            Email: <input type="email" onChange={handleEmail} required /> <br />
            Password: <input type="password" onChange={handlePassword} required /> <br />
            <button onClick={handleLogin}>Login</button>
            New User? <a href='/Sign'>Sign In</a>
        </div>
    );
}
